CREATE TABLE "action_policies" (
  "id" TEXT NOT NULL,
  "workspace_id" TEXT NOT NULL,
  "scope_type" TEXT NOT NULL CHECK("scope_type" IN ('workspace', 'agent', 'space')),
  "scope_id" TEXT NOT NULL DEFAULT '',
  "action_class" TEXT NULL CHECK("action_class" IN ('fileDelete', 'fileWriteOutsideWorktree', 'gitCommit', 'gitPush', 'prCreate', 'prPublish', 'vendorSyncWrite', 'networkEgress', 'secretAccess', 'packageInstall', 'processSpawn', 'workspaceMutation', 'enclosureControl', 'hostExecution')),
  "command_prefix" TEXT NULL,
  "decision" TEXT NOT NULL DEFAULT 'prompt' CHECK("decision" IN ('allow', 'prompt', 'deny')),
  "provenance" TEXT NOT NULL DEFAULT 'user' CHECK("provenance" IN ('user', 'remembered')),
  "constraint_json" TEXT NULL CHECK(json_valid("constraint_json") AND json_type("constraint_json") = 'object'),
  "expires_at" INTEGER NULL,
  "enforcement" TEXT NULL CHECK("enforcement" IN ('advisory', 'soft', 'hard')),
  "created_by" TEXT NULL,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)),
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)),
  PRIMARY KEY ("id"),
  CHECK ((action_class IS NULL) <> (command_prefix IS NULL)),
  CHECK ((scope_type = 'workspace') = (scope_id = ''))
);
CREATE INDEX idx_action_policies_scope ON action_policies (scope_type, scope_id);
CREATE UNIQUE INDEX uq_action_policies_class_rule ON action_policies (scope_type, scope_id, action_class, provenance, coalesce(constraint_json, ''),(provenance = 'user' AND constraint_json IS NULL AND expires_at IS NULL)) WHERE action_class IS NOT NULL;
CREATE UNIQUE INDEX uq_action_policies_command_rule ON action_policies (scope_type, scope_id, command_prefix, provenance, coalesce(constraint_json, ''),(provenance = 'user' AND constraint_json IS NULL AND expires_at IS NULL)) WHERE command_prefix IS NOT NULL;

