  "started_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)),
  "completed_at" INTEGER NULL,
  "status" TEXT NOT NULL DEFAULT 'pending' CHECK("status" IN ('pending', 'running', 'completed', 'error')),
  "summary" TEXT NULL,
  "adapter" TEXT NULL,
  "model_id" TEXT NULL,
  "pid" INTEGER NULL,
  "log_path" TEXT NULL,
  "input_tokens" INTEGER NOT NULL DEFAULT 0,
  "output_tokens" INTEGER NOT NULL DEFAULT 0,
  "thought_tokens" INTEGER NOT NULL DEFAULT 0,
  "cached_read_tokens" INTEGER NOT NULL DEFAULT 0,
  "cached_write_tokens" INTEGER NOT NULL DEFAULT 0,
  "cost_micros" INTEGER NOT NULL DEFAULT 0,
