  "latency_json" TEXT NULL CHECK(json_valid("latency_json") AND json_type("latency_json") = 'array'),
  "verification_status" TEXT NULL CHECK("verification_status" IN ('unverified', 'passed', 'failed')),
  "agent_role" TEXT NULL CHECK("agent_role" IN ('main', 'sub', 'advisor')),
  "duration_ms" INTEGER NULL,
  "time_to_first_token_ms" INTEGER NULL,
  "liveness_class" TEXT NULL CHECK("liveness_class" IN ('alive', 'productive', 'completed', 'blocked', 'empty', 'looping', 'failed', 'stalled', 'dead')),
  "error_family" TEXT NULL CHECK("error_family" IN ('transientUpstream', 'sandboxInfrastructure', 'budgetExceeded', 'processLost', 'silentRun', 'unknown')),
  "error_code" TEXT NULL,
  "pipeline_run_id" TEXT NULL REFERENCES pipeline_runs (id) ON DELETE SET NULL,
  "pipeline_step_id" TEXT NULL,
  "memory_reads" INTEGER NOT NULL DEFAULT 0,
  "memory_writes" INTEGER NOT NULL DEFAULT 0,
  "code_graph_calls" INTEGER NOT NULL DEFAULT 0,
  "last_output_at" INTEGER NULL,
  "output_contract_mode" TEXT NULL DEFAULT 'strict' CHECK("output_contract_mode" IN ('strict', 'permissive')),
  "output_rejections" INTEGER NOT NULL DEFAULT 0,
  "retry_of_run_id" TEXT NULL REFERENCES agent_run_logs (id) ON DELETE SET NULL,
  "retry_attempt" INTEGER NOT NULL DEFAULT 0,
  "parent_run_id" TEXT NULL REFERENCES agent_run_logs (id) ON DELETE SET NULL,
  "spawn_tool_call_id" TEXT NULL,
  "end_reason" TEXT NULL CHECK("end_reason" IN ('completed', 'error', 'stopped_by_user', 'budget', 'silence', 'usage_limit', 'server_stopped')),
  "wake_ids" TEXT NOT NULL DEFAULT '[]' CHECK(json_valid("wake_ids") AND json_type("wake_ids") = 'array'),
  "requested_by_user_id" TEXT NULL,
  "wake_reason" TEXT NULL CHECK("wake_reason" IN ('user_message', 'assignment', 'recovery', 'child_completed', 'schedule', 'pipeline_step', 'goal_continuation', 'goal_verification', 'goal_review', 'watch', 'peer_message', 'peer_reply', 'limit_reset', 'improvement_review')),
  "started_by_run_id" TEXT NULL,
  PRIMARY KEY ("id")
);
