CREATE TABLE "agent_wakes" (
  "id" TEXT NOT NULL,
  "workspace_id" TEXT NOT NULL,
  "space_id" TEXT NOT NULL,
  "conversation_id" TEXT NOT NULL REFERENCES conversations (id) ON DELETE CASCADE,
  "agent_id" TEXT NOT NULL REFERENCES agents (id) ON DELETE CASCADE,
  "reason" TEXT NOT NULL CHECK("reason" IN ('user_message', 'assignment', 'recovery', 'child_completed', 'schedule', 'pipeline_step', 'goal_continuation', 'goal_verification', 'goal_review', 'watch', 'peer_message', 'peer_reply', 'limit_reset', 'improvement_review')),
  "lane" TEXT NOT NULL DEFAULT 'aside' CHECK("lane" IN ('aside', 'follow_up')),
  "payload" TEXT NOT NULL,
  "detail" TEXT NOT NULL DEFAULT '{}' CHECK(json_valid("detail") AND json_type("detail") = 'object'),
  "run_options" TEXT NULL CHECK(json_valid("run_options") AND json_type("run_options") = 'object'),
  "dedup_key" TEXT NOT NULL,
  "not_before" INTEGER NOT NULL,
  "expires_at" INTEGER NULL,
  "requested_by_user_id" TEXT NULL,
  "chain" TEXT NOT NULL DEFAULT '[]' CHECK(json_valid("chain") AND json_type("chain") = 'array'),
  "expects_reply" INTEGER NOT NULL DEFAULT 0 CHECK ("expects_reply" IN (0, 1)),
  "state" TEXT NOT NULL DEFAULT 'pending' CHECK("state" IN ('pending', 'held', 'claimed', 'delivered', 'skipped', 'expired', 'cancelled')),
  "state_reason" TEXT NULL,
  "delivered_run_id" TEXT NULL,
  "attempt" INTEGER NOT NULL DEFAULT 0,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)),
  "claimed_at" INTEGER NULL,
  "settled_at" INTEGER NULL,
  PRIMARY KEY ("id"),
  CHECK (length(payload) <= 4000),
  CHECK (attempt >= 0),
  CHECK (expires_at IS NULL OR expires_at >= created_at)
);
