CREATE TABLE "code_execution_calls" (
  "execution_id" TEXT NOT NULL REFERENCES code_executions (id) ON DELETE CASCADE,
  "sequence" INTEGER NOT NULL,
  "tool_call_id" TEXT NOT NULL,
  "tool_name" TEXT NOT NULL,
  "start_offset_ms" INTEGER NOT NULL,
  "duration_ms" INTEGER NOT NULL,
  "status" TEXT NOT NULL CHECK("status" IN ('completed', 'failed', 'denied', 'cancelled', 'timed_out', 'unknown_tool', 'invalid_args')),
  "gate_decision" TEXT NULL CHECK("gate_decision" IN ('allowed', 'approved', 'denied')),
  "approval_wait_ms" INTEGER NOT NULL DEFAULT 0,
  "argument_bytes" INTEGER NOT NULL DEFAULT 0,
  "result_bytes" INTEGER NOT NULL DEFAULT 0,
  "arguments" TEXT NOT NULL DEFAULT '{}',
  "error" TEXT NULL,
  "site_line" INTEGER NULL,
  "site_column" INTEGER NULL,
  PRIMARY KEY ("execution_id", "sequence"),
  CHECK ((site_line IS NULL) = (site_column IS NULL) AND (site_line IS NULL OR (site_line >= 1 AND site_column >= 1)))
);

CREATE TABLE "code_execution_payloads" (
  "execution_id" TEXT NOT NULL REFERENCES code_executions (id) ON DELETE CASCADE,
  "source" TEXT NOT NULL,
  "output" TEXT NOT NULL DEFAULT '',
  "console" TEXT NOT NULL DEFAULT '',
  "error_name" TEXT NULL,
  PRIMARY KEY ("execution_id")
);

CREATE TABLE "code_executions" (
  "id" TEXT NOT NULL,
  "run_id" TEXT NOT NULL REFERENCES agent_run_logs (id) ON DELETE CASCADE,
  "tool_call_id" TEXT NOT NULL,
  "id_suffix" INTEGER NOT NULL,
  "surface" TEXT NOT NULL CHECK("surface" IN ('harness', 'mcp')),
  "conversation_id" TEXT NULL REFERENCES conversations (id) ON DELETE SET NULL,
  "agent_id" TEXT NULL REFERENCES agents (id) ON DELETE SET NULL,
  "space_id" TEXT NULL REFERENCES spaces (id) ON DELETE CASCADE,
  "description" TEXT NOT NULL DEFAULT '',
  "started_at_ms" INTEGER NOT NULL,
  "duration_ms" INTEGER NOT NULL,
  "status" TEXT NOT NULL CHECK("status" IN ('running', 'completed', 'failed', 'timed_out', 'cancelled', 'memory_exceeded', 'output_exceeded', 'sandbox_error', 'refused')),
  "error_kind" TEXT NULL CHECK("error_kind" IN ('script_error', 'stalled', 'cpu', 'heap', 'output', 'deadline', 'cancelled', 'shutdown', 'server_stopped', 'internal', 'start', 'lockdown', 'exited', 'protocol', 'frame_too_large', 'call_cap', 'output_overrun', 'store_overrun', 'stdin_stalled', 'unresponsive', 'host_error', 'invalid_tool_call_id', 'execution_id', 'unavailable', 'source_too_large', 'catalog', 'run_busy', 'server_busy', 'no_run_log', 'audit_unavailable', 'space_gone')),
  "source_hash" TEXT NOT NULL,
  "source_bytes" INTEGER NOT NULL,
  "cpu_ms" INTEGER NULL,
  "peak_heap_bytes" INTEGER NULL,
  "calls_completed" INTEGER NOT NULL DEFAULT 0,
  "calls_failed" INTEGER NOT NULL DEFAULT 0,
  "calls_denied" INTEGER NOT NULL DEFAULT 0,
  "calls_cancelled" INTEGER NOT NULL DEFAULT 0,
  "calls_timed_out" INTEGER NOT NULL DEFAULT 0,
  "calls_unknown_tool" INTEGER NOT NULL DEFAULT 0,
  "calls_invalid_args" INTEGER NOT NULL DEFAULT 0,
  "question_count" INTEGER NOT NULL DEFAULT 0,
  "output_bytes" INTEGER NOT NULL DEFAULT 0,
  "output_truncated" INTEGER NOT NULL DEFAULT 0 CHECK ("output_truncated" IN (0, 1)),
  "engine_version" TEXT NULL,
  "lockdown_json" TEXT NULL CHECK(json_valid("lockdown_json") AND json_type("lockdown_json") = 'object'),
  "limits_json" TEXT NOT NULL CHECK(json_valid("limits_json") AND json_type("limits_json") = 'object'),
  PRIMARY KEY ("id")
);
CREATE INDEX idx_code_executions_agent_started ON code_executions (agent_id, started_at_ms, id);
CREATE INDEX idx_code_executions_conversation_started ON code_executions (conversation_id, started_at_ms, id);
CREATE INDEX idx_code_executions_run_started ON code_executions (run_id, started_at_ms, id);
CREATE INDEX idx_code_executions_run_tool_call_suffix ON code_executions (run_id, tool_call_id, id_suffix);
CREATE INDEX idx_code_executions_space_started ON code_executions (space_id, started_at_ms, id);
CREATE INDEX idx_code_executions_started ON code_executions (started_at_ms, id);
CREATE INDEX idx_code_executions_status_started ON code_executions (status, started_at_ms, id);
CREATE INDEX idx_code_executions_tool_call_started ON code_executions (tool_call_id, started_at_ms, id);

CREATE TABLE "code_mode_store" (
  "conversation_id" TEXT NOT NULL REFERENCES conversations (id) ON DELETE CASCADE,
  "agent_id" TEXT NOT NULL REFERENCES agents (id) ON DELETE CASCADE,
