  "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)),
  PRIMARY KEY ("conversation_id", "agent_id", "key")
);
CREATE INDEX idx_code_mode_store_agent ON code_mode_store (agent_id);

CREATE TABLE "conversation_activity" (
  "conversation_id" TEXT NOT NULL REFERENCES conversations (id) ON DELETE CASCADE,
  "space_id" TEXT NOT NULL REFERENCES spaces (id) ON DELETE CASCADE,
  "last_message_at" INTEGER NOT NULL,
  "last_agent_message_at" INTEGER NULL,
  "last_agent_message_seq" INTEGER NULL,
  "open_question_count" INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY ("conversation_id")
);
CREATE INDEX idx_conversation_activity_spaceId ON conversation_activity (space_id);

CREATE TABLE "conversation_goals" (
  "conversation_id" TEXT NOT NULL REFERENCES conversations (id) ON DELETE CASCADE,
  "workspace_id" TEXT NOT NULL,
  "title" TEXT NOT NULL,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)),
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)),
  PRIMARY KEY ("conversation_id")
);

CREATE TABLE "conversation_message_embeddings" (
  "message_id" TEXT NOT NULL REFERENCES conversation_messages (id) ON DELETE CASCADE,
  "embedding" BLOB NOT NULL,
  PRIMARY KEY ("message_id")
);

CREATE TABLE "conversation_messages" (
  "id" TEXT NOT NULL,
  "space_id" TEXT NOT NULL REFERENCES spaces (id) ON DELETE CASCADE,
  "conversation_id" TEXT NOT NULL REFERENCES conversations (id) ON DELETE CASCADE,
  "sender_id" TEXT NOT NULL,
  "sender_type" TEXT NOT NULL CHECK("sender_type" IN ('user', 'agent', 'system')),
  "revision" INTEGER NOT NULL DEFAULT 0,
  "content" TEXT NOT NULL,
  "content_chars" INTEGER NOT NULL DEFAULT 0,
  "message_type" TEXT NOT NULL DEFAULT 'text' CHECK("message_type" IN ('text', 'system', 'ticket_card', 'agent_turn', 'review_node', 'hire_proposal', 'review_summary', 'plan', 'user_question', 'orchestration_proposal', 'artifact', 'compaction', 'steering')),
  "answered" INTEGER NOT NULL DEFAULT 0 CHECK ("answered" IN (0, 1)),
  "plan_status" TEXT NULL CHECK("plan_status" IN ('pending', 'approved', 'refining')),
  "steer_state" TEXT NULL CHECK("steer_state" IN ('queued', 'injected', 'converted', 'held')),
  "list_metadata" TEXT NULL CHECK(json_valid("list_metadata") AND json_type("list_metadata") = 'object'),
  "transcript_chars" INTEGER NOT NULL DEFAULT 0,
  "context_tokens" INTEGER NULL,
  "context_window_tokens" INTEGER NULL,
  "parent_message_id" TEXT REFERENCES conversation_messages(id) ON DELETE SET NULL,
  "compacted" INTEGER NOT NULL DEFAULT 0 CHECK ("compacted" IN (0, 1)),
  "reverted" INTEGER NOT NULL DEFAULT 0 CHECK ("reverted" IN (0, 1)),
  "reverted_at" INTEGER NULL,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)),
  PRIMARY KEY ("id")
);
CREATE INDEX idx_conversation_messages_context_reading ON conversation_messages (conversation_id, created_at, context_tokens, context_window_tokens) WHERE reverted = 0 AND context_tokens IS NOT NULL;
CREATE INDEX idx_conversation_messages_conversation_created ON conversation_messages (conversation_id, created_at);
CREATE INDEX idx_conversation_messages_live_activity ON conversation_messages (space_id, conversation_id, created_at, sender_type) WHERE reverted = 0;
CREATE INDEX idx_conversation_messages_live_chars ON conversation_messages (conversation_id, message_type, content_chars, transcript_chars) WHERE reverted = 0 AND compacted = 0;
CREATE INDEX idx_conversation_messages_messageType ON conversation_messages (message_type);
CREATE INDEX idx_conversation_messages_open_questions ON conversation_messages (conversation_id) WHERE message_type = 'user_question' AND answered = 0 AND reverted = 0;
CREATE INDEX idx_conversation_messages_outline ON conversation_messages (conversation_id, created_at, space_id, id, sender_id, sender_type, message_type, content_chars, answered, steer_state, revision) WHERE reverted = 0 AND revision >= 0;
CREATE INDEX idx_conversation_messages_parentMessageId ON conversation_messages (parent_message_id);
CREATE INDEX idx_conversation_messages_queued_steering ON conversation_messages (conversation_id, space_id) WHERE steer_state = 'queued';
CREATE INDEX idx_conversation_messages_space_created ON conversation_messages (space_id, created_at);
CREATE TRIGGER conversation_messages_ad AFTER DELETE ON conversation_messages BEGIN INSERT INTO conversation_messages_fts(conversation_messages_fts, rowid, content, space_id) VALUES ('delete', old.rowid, old.content, old.space_id); END;
CREATE TRIGGER conversation_messages_ai AFTER INSERT ON conversation_messages BEGIN INSERT INTO conversation_messages_fts(rowid, content, space_id) VALUES (new.rowid, new.content, new.space_id); END;
CREATE TRIGGER conversation_messages_au AFTER UPDATE OF content, space_id ON conversation_messages BEGIN INSERT INTO conversation_messages_fts(conversation_messages_fts, rowid, content, space_id) VALUES ('delete', old.rowid, old.content, old.space_id); INSERT INTO conversation_messages_fts(rowid, content, space_id) VALUES (new.rowid, new.content, new.space_id); END;
CREATE TRIGGER conversation_messages_revision_au AFTER UPDATE ON conversation_messages WHEN new.revision <= old.revision BEGIN UPDATE conversation_messages SET revision = old.revision + 1 WHERE rowid = new.rowid; END;

CREATE VIRTUAL TABLE conversation_messages_fts USING fts5(content, space_id, content=conversation_messages, content_rowid=rowid);

