  "target_ref" TEXT NULL,
  "change" TEXT NOT NULL,
  "evidence" TEXT NOT NULL DEFAULT '{}' CHECK(json_valid("evidence") AND json_type("evidence") = 'object'),
  "expected" TEXT NOT NULL,
  "status" TEXT NOT NULL DEFAULT 'proposed' CHECK("status" IN ('proposed', 'accepted', 'rejected', 'rolled_back', 'expired')),
  "before_text" TEXT NULL,
  "after_text" TEXT NULL,
  "applied_ref" TEXT NULL,
  "candidate_revision_id" TEXT NULL,
  "campaign_id" TEXT NULL,
  "campaign_state" TEXT NOT NULL DEFAULT 'none' CHECK("campaign_state" IN ('none', 'staging', 'running', 'passed', 'failed')),
  "decided_by_user_id" TEXT NULL,
  "decided_at" INTEGER NULL,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)),
  "expires_at" INTEGER NOT NULL,
  PRIMARY KEY ("id"),
  CHECK (length(change) BETWEEN 1 AND 600),
  CHECK (length(expected) BETWEEN 1 AND 600),
  CHECK (expires_at >= created_at)
);
CREATE INDEX idx_improvement_proposals_agent_status ON improvement_proposals (agent_id, status);
CREATE INDEX idx_improvement_proposals_conversation ON improvement_proposals (conversation_id);
CREATE INDEX idx_improvement_proposals_goal ON improvement_proposals (goal_id);
CREATE INDEX idx_improvement_proposals_status_created ON improvement_proposals (status, created_at);

