  "conflict_type" TEXT NOT NULL DEFAULT 'contradiction' CHECK("conflict_type" IN ('contradiction', 'cross_agent')),
  "resolution" TEXT NULL CHECK("resolution" IN ('superseded')),
  "winning_fact_id" TEXT NULL REFERENCES memory_facts (id) ON DELETE SET NULL,
  "resolved_at" INTEGER NULL,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)),
  PRIMARY KEY ("id")
);
CREATE INDEX idx_memory_conflicts_factA ON memory_conflicts (fact_a_id);
CREATE INDEX idx_memory_conflicts_factB ON memory_conflicts (fact_b_id);
CREATE INDEX idx_memory_conflicts_winner ON memory_conflicts (winning_fact_id);

