  "facts_updated" INTEGER NOT NULL DEFAULT 0,
  "conflicts_detected" INTEGER NOT NULL DEFAULT 0,
  "evicted" INTEGER NOT NULL DEFAULT 0,
  "started_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)),
  "finished_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)),
