CREATE TABLE "memory_fact_embeddings" (
  "fact_id" TEXT NOT NULL REFERENCES memory_facts (id) ON DELETE CASCADE,
  "embedding" BLOB NOT NULL,
  PRIMARY KEY ("fact_id")
);

CREATE TABLE "memory_facts" (
  "id" TEXT NOT NULL,
  "workspace_id" TEXT NOT NULL,
  "domain" TEXT NOT NULL,
  "topic" TEXT NOT NULL,
  "content" TEXT NOT NULL,
  "source_observation_ids" TEXT NOT NULL DEFAULT '[]' CHECK(json_valid("source_observation_ids") AND json_type("source_observation_ids") = 'array'),
  "confidence" REAL NOT NULL DEFAULT 1.0,
  "superseded_by" TEXT NULL,
  "authored_by_agent_id" TEXT NULL REFERENCES agents (id) ON DELETE SET NULL,
  "authored_by_role" TEXT NULL CHECK("authored_by_role" IN ('ceo', 'coder', 'reviewer', 'qa', 'designer', 'security', 'devops', 'pm', 'general')),
  "memory_type" TEXT NOT NULL DEFAULT 'fact' CHECK("memory_type" IN ('fact', 'preference', 'decision', 'commitment', 'goal', 'event', 'instruction', 'relationship', 'context', 'learning', 'observation', 'error', 'artifact', 'request', 'unknown')),
  "veracity" TEXT NOT NULL DEFAULT 'stated' CHECK("veracity" IN ('stated', 'inferred', 'tool', 'imported', 'unknown')),
  "valid_until" INTEGER NULL,
  "recall_count" INTEGER NOT NULL DEFAULT 0,
  "last_recalled_at" INTEGER NULL,
  "temporal_tags" TEXT NULL CHECK(json_valid("temporal_tags") AND json_type("temporal_tags") = 'array'),
  "mention_count" INTEGER NOT NULL DEFAULT 1,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)),
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)),
  PRIMARY KEY ("id")
);
CREATE INDEX idx_memory_facts_author ON memory_facts (authored_by_agent_id);
CREATE INDEX idx_memory_facts_supersededBy ON memory_facts (superseded_by);
CREATE INDEX idx_memory_facts_topic ON memory_facts (topic);
CREATE TRIGGER memory_facts_ad AFTER DELETE ON memory_facts BEGIN INSERT INTO memory_facts_fts(memory_facts_fts, rowid, topic, content, workspace_id) VALUES ('delete', old.rowid, old.topic, old.content, old.workspace_id); END;
CREATE TRIGGER memory_facts_ai AFTER INSERT ON memory_facts BEGIN INSERT INTO memory_facts_fts(rowid, topic, content, workspace_id) VALUES (new.rowid, new.topic, new.content, new.workspace_id); END;
CREATE TRIGGER memory_facts_au AFTER UPDATE ON memory_facts BEGIN INSERT INTO memory_facts_fts(memory_facts_fts, rowid, topic, content, workspace_id) VALUES ('delete', old.rowid, old.topic, old.content, old.workspace_id); INSERT INTO memory_facts_fts(rowid, topic, content, workspace_id) VALUES (new.rowid, new.topic, new.content, new.workspace_id); END;

CREATE VIRTUAL TABLE memory_facts_fts USING fts5(topic, content, workspace_id, content=memory_facts, content_rowid=rowid);

