  "space_id" TEXT NULL REFERENCES spaces (id) ON DELETE SET NULL,
  "orchestrator_agent_id" TEXT NULL REFERENCES agents (id) ON DELETE SET NULL,
  "status" TEXT NOT NULL DEFAULT 'proposed' CHECK("status" IN ('proposed', 'approved', 'executing', 'synthesizing', 'completed', 'failed', 'cancelled')),
  "proposal_json" TEXT NOT NULL CHECK(json_valid("proposal_json") AND json_type("proposal_json") = 'object'),
  "revision" INTEGER NOT NULL DEFAULT 1,
  "approved_revision" INTEGER NULL,
  "pipeline_template_id" TEXT NULL REFERENCES pipeline_templates (id) ON DELETE SET NULL,
  "pipeline_run_id" TEXT NULL REFERENCES pipeline_runs (id) ON DELETE SET NULL,
  "team_id" TEXT NULL REFERENCES teams (id) ON DELETE SET NULL,
  "project_id" TEXT NULL REFERENCES projects (id) ON DELETE SET NULL,
  "estimated_cost_micros" INTEGER NULL,
  "max_cost_micros" INTEGER NULL,
  "hired_agent_ids_json" TEXT NOT NULL DEFAULT '[]' CHECK(json_valid("hired_agent_ids_json") AND json_type("hired_agent_ids_json") = 'array'),
  "approved_node_keys_json" TEXT NULL CHECK(json_valid("approved_node_keys_json") AND json_type("approved_node_keys_json") = 'array'),
  "error_message" TEXT NULL,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)),
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)),
  "completed_at" INTEGER NULL,
  PRIMARY KEY ("id")
);
