CREATE INDEX idx_orchestrations_pipelineRun ON orchestrations (pipeline_run_id);
CREATE INDEX idx_orchestrations_project ON orchestrations (project_id);
CREATE INDEX idx_orchestrations_space ON orchestrations (space_id);
CREATE INDEX idx_orchestrations_status ON orchestrations (status);
CREATE INDEX idx_orchestrations_team ON orchestrations (team_id);
CREATE INDEX idx_orchestrations_template ON orchestrations (pipeline_template_id);

CREATE TABLE "peer_asks" (
  "id" TEXT NOT NULL,
  "workspace_id" TEXT NOT NULL,
  "kind" TEXT NOT NULL DEFAULT 'ask' CHECK("kind" IN ('ask', 'consult', 'review')),
  "mode" TEXT NOT NULL DEFAULT 'wait' CHECK("mode" IN ('wait', 'background')),
  "asker_agent_id" TEXT NOT NULL REFERENCES agents (id) ON DELETE CASCADE,
  "asker_run_id" TEXT NULL,
  "asker_conversation_id" TEXT NOT NULL REFERENCES conversations (id) ON DELETE CASCADE,
  "asker_space_id" TEXT NOT NULL,
  "recipient_agent_id" TEXT NOT NULL REFERENCES agents (id) ON DELETE CASCADE,
  "recipient_conversation_id" TEXT NULL,
  "recipient_space_id" TEXT NULL,
  "question_message_id" TEXT NULL,
  "question_hash" TEXT NOT NULL,
  "dispatched_run_id" TEXT NULL,
  "chain" TEXT NOT NULL DEFAULT '[]' CHECK(json_valid("chain") AND json_type("chain") = 'array'),
  "status" TEXT NOT NULL DEFAULT 'pending' CHECK("status" IN ('pending', 'answered', 'failed', 'expired', 'cancelled')),
  "reply_message_id" TEXT NULL,
  "reply_inline" INTEGER NOT NULL DEFAULT 0 CHECK ("reply_inline" IN (0, 1)),
  "error" TEXT NULL,
  "requested_by_user_id" TEXT NULL,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)),
  "expires_at" INTEGER NOT NULL,
  "settled_at" INTEGER NULL,
  "promised_at" INTEGER NULL,
  "blocked_noticed_at" INTEGER NULL,
  "stall_noticed_run_id" TEXT NULL,
  PRIMARY KEY ("id"),
  CHECK (asker_agent_id <> recipient_agent_id),
  CHECK (expires_at >= created_at),
  CHECK (error IS NULL OR length(error) <= 2000)
);
CREATE INDEX idx_peer_asks_asker_conversation_status ON peer_asks (asker_conversation_id, status);
CREATE INDEX idx_peer_asks_asker_status ON peer_asks (asker_agent_id, status);
CREATE INDEX idx_peer_asks_dispatched_run ON peer_asks (dispatched_run_id);
CREATE INDEX idx_peer_asks_recipient_status ON peer_asks (recipient_agent_id, status);
CREATE INDEX idx_peer_asks_status_expires ON peer_asks (status, expires_at);

CREATE TABLE "pending_pr_replies" (
  "run_log_id" TEXT NOT NULL REFERENCES agent_run_logs (id) ON DELETE CASCADE,
  "reply_json" TEXT NOT NULL CHECK(json_valid("reply_json") AND json_type("reply_json") = 'object'),
