CREATE TABLE "pipeline_run_snapshots" (
  "run_id" TEXT NOT NULL REFERENCES pipeline_runs (id) ON DELETE CASCADE,
  "template_snapshot_json" TEXT NOT NULL CHECK(json_valid("template_snapshot_json") AND json_type("template_snapshot_json") = 'object'),
  PRIMARY KEY ("run_id")
);

CREATE TABLE "pipeline_runs" (
  "id" TEXT NOT NULL,
  "template_id" TEXT NOT NULL,
  "workspace_id" TEXT NOT NULL,
  "status" TEXT NOT NULL DEFAULT 'pending' CHECK("status" IN ('pending', 'queued', 'running', 'suspended', 'completed', 'failed', 'cancelled')),
  "state_json" TEXT NOT NULL DEFAULT '{}' CHECK(json_valid("state_json") AND json_type("state_json") = 'object'),
  "trigger_event_type" TEXT NULL,
  "trigger_payload_json" TEXT NULL CHECK(json_valid("trigger_payload_json") AND json_type("trigger_payload_json") = 'object'),
  "started_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)),
  "attempt_started_at" INTEGER NULL,
  "finished_at" INTEGER NULL,
  "active_ms" INTEGER NOT NULL DEFAULT 0,
  "last_resumed_at" INTEGER NULL,
  "error_message" TEXT NULL,
  "error_stack_trace" TEXT NULL,
  "dedup_key" TEXT NULL,
  "parent_pipeline_run_id" TEXT NULL REFERENCES pipeline_runs (id) ON DELETE SET NULL,
  "parent_step_id" TEXT NULL,
  "template_version" INTEGER NOT NULL DEFAULT 1,
  "attempt_count" INTEGER NOT NULL DEFAULT 1,
  "total_cost_micros" INTEGER NOT NULL DEFAULT 0,
  "total_tokens" INTEGER NOT NULL DEFAULT 0,
  "dry_run" INTEGER NOT NULL DEFAULT 0 CHECK ("dry_run" IN (0, 1)),
  "is_projection" INTEGER NOT NULL DEFAULT 0 CHECK ("is_projection" IN (0, 1)),
  PRIMARY KEY ("id")
);
CREATE INDEX idx_pipeline_runs_parent ON pipeline_runs (parent_pipeline_run_id);
CREATE INDEX idx_pipeline_runs_started ON pipeline_runs (started_at);
CREATE INDEX idx_pipeline_runs_status ON pipeline_runs (status);
CREATE INDEX idx_pipeline_runs_template_status ON pipeline_runs (template_id, status, started_at);
CREATE UNIQUE INDEX uq_pipeline_runs_active_dedup ON pipeline_runs (template_id, dedup_key) WHERE dedup_key IS NOT NULL AND status IN ('pending', 'queued', 'running', 'suspended');

CREATE TABLE "pipeline_step_runs" (
  "id" TEXT NOT NULL,
  "pipeline_run_id" TEXT NOT NULL REFERENCES pipeline_runs (id) ON DELETE CASCADE,
  "step_id" TEXT NOT NULL,
  "status" TEXT NOT NULL DEFAULT 'pending' CHECK("status" IN ('pending', 'running', 'suspended', 'completed', 'failed', 'skipped', 'cancelled')),
  "input_json" TEXT NULL CHECK(json_valid("input_json")),
  "output_json" TEXT NULL CHECK(json_valid("output_json")),
  "space_id" TEXT NULL REFERENCES spaces (id) ON DELETE SET NULL,
  "error_message" TEXT NULL,
  "error_stack_trace" TEXT NULL,
  "attempt_count" INTEGER NOT NULL DEFAULT 0,
  "attempt_history" TEXT NOT NULL DEFAULT '[]' CHECK(json_valid("attempt_history") AND json_type("attempt_history") = 'array'),
