  "priority" INTEGER NOT NULL DEFAULT 0,
  "labels" TEXT NOT NULL DEFAULT '[]' CHECK(json_valid("labels") AND json_type("labels") = 'array'),
  "status" TEXT NOT NULL DEFAULT 'open' CHECK("status" IN ('backlog', 'open', 'inProgress', 'blocked', 'inReview', 'done', 'failed', 'cancelled')),
  "raw_status" TEXT NULL,
  "external_synced_at" INTEGER NULL,
  "parent_ticket_id" TEXT NULL REFERENCES tickets (id) ON DELETE SET NULL,
  "project_id" TEXT NULL REFERENCES projects (id) ON DELETE SET NULL,
  "assigned_agent_id" TEXT NULL,
  "assignee_type" TEXT NOT NULL DEFAULT 'agent' CHECK("assignee_type" IN ('user', 'agent')),
  "created_by_type" TEXT NOT NULL DEFAULT 'system' CHECK("created_by_type" IN ('user', 'agent', 'system')),
  "created_by_id" TEXT NULL,
  "assigned_team_id" TEXT NULL REFERENCES teams (id) ON DELETE SET NULL,
  "delegated_by_agent_id" TEXT NULL REFERENCES agents (id) ON DELETE SET NULL,
  "delegation_depth" INTEGER NOT NULL DEFAULT 0,
  "delegation_root_ticket_id" TEXT NULL REFERENCES tickets (id) ON DELETE SET NULL,
  "delegated_from_conversation_id" TEXT NULL,
  "space_id" TEXT NULL REFERENCES spaces (id) ON DELETE SET NULL,
  "error_message" TEXT NULL,
  "linked_pr_ids" TEXT NOT NULL DEFAULT '[]' CHECK(json_valid("linked_pr_ids") AND json_type("linked_pr_ids") = 'array'),
  "metadata" TEXT NOT NULL DEFAULT '{}' CHECK(json_valid("metadata") AND json_type("metadata") = 'object'),
  "version" INTEGER NOT NULL DEFAULT 0,
  "origin_kind" TEXT NOT NULL DEFAULT 'manual' CHECK("origin_kind" IN ('manual', 'pipelineStep', 'agentDelegation', 'externalSync', 'recovery')),
  "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)),
  "started_at" INTEGER NULL,
  "blocked_at" INTEGER NULL,
  "cancelled_at" INTEGER NULL,
  "completed_at" INTEGER NULL,
  "finished_at" INTEGER NULL,
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)),
  PRIMARY KEY ("id")
);
