CREATE TABLE "wake_rules" (
  "id" TEXT NOT NULL,
  "workspace_id" TEXT NOT NULL,
  "space_id" TEXT NOT NULL,
  "conversation_id" TEXT NOT NULL REFERENCES conversations (id) ON DELETE CASCADE,
  "agent_id" TEXT NOT NULL REFERENCES agents (id) ON DELETE CASCADE,
  "trigger_kind" TEXT NOT NULL CHECK("trigger_kind" IN ('at', 'every', 'cron', 'self_paced', 'event')),
  "trigger_at" INTEGER NULL,
  "interval_seconds" INTEGER NULL,
  "cron_expression" TEXT NULL,
  "time_zone" TEXT NULL,
  "event_kind" TEXT NULL CHECK("event_kind" IN ('pr_checks', 'pr_review', 'pr_merged', 'environment', 'ticket', 'pipeline_run')),
  "event_target_id" TEXT NULL,
  "note" TEXT NOT NULL,
  "note_edited_by_user_id" TEXT NULL,
  "root_rule_id" TEXT NULL,
  "deliver" TEXT NOT NULL DEFAULT 'run' CHECK("deliver" IN ('run', 'notify')),
  "when_busy" TEXT NOT NULL DEFAULT 'skip' CHECK("when_busy" IN ('skip', 'queue')),
  "max_runs" INTEGER NULL,
  "cost_cap_micros" INTEGER NOT NULL,
  "expires_at" INTEGER NOT NULL,
  "run_count" INTEGER NOT NULL DEFAULT 0,
  "skip_count" INTEGER NOT NULL DEFAULT 0,
  "cost_micros" INTEGER NOT NULL DEFAULT 0,
  "last_fired_at" INTEGER NULL,
  "next_fire_at" INTEGER NULL,
  "next_delay_seconds" INTEGER NULL,
  "goal_id" TEXT NULL REFERENCES agent_goal_runs (id) ON DELETE CASCADE,
  "origin" TEXT NOT NULL CHECK("origin" IN ('agent', 'person')),
  "created_by_run_id" TEXT NULL,
  "created_by_user_id" TEXT NULL,
  "requested_by_user_id" TEXT NULL,
  "status" TEXT NOT NULL DEFAULT 'active' CHECK("status" IN ('active', 'paused', 'ended')),
  "end_reason" TEXT NULL CHECK("end_reason" IN ('fired', 'expired', 'run_cap', 'cost_cap', 'goal_ended', 'cancelled', 'member_removed', 'invalid_row')),
  "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)),
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)),
  PRIMARY KEY ("id"),
  CHECK ((trigger_kind <> 'at' OR trigger_at IS NOT NULL) AND (trigger_kind <> 'every' OR interval_seconds >= 60) AND (trigger_kind <> 'cron' OR (cron_expression IS NOT NULL AND time_zone IS NOT NULL)) AND (trigger_kind <> 'event' OR event_kind IS NOT NULL) AND (event_kind NOT IN ('ticket', 'pipeline_run') OR event_target_id IS NOT NULL)),
  CHECK ((status = 'ended') = (end_reason IS NOT NULL)),
  CHECK (length(note) <= 4000),
  CHECK (expires_at >= created_at),
  CHECK (run_count >= 0 AND skip_count >= 0 AND cost_micros >= 0),
  CHECK (cost_cap_micros > 0 AND (max_runs IS NULL OR max_runs > 0))
);
CREATE INDEX idx_wake_rules_agent_status ON wake_rules (agent_id, status);
CREATE INDEX idx_wake_rules_conversation_agent_status ON wake_rules (conversation_id, agent_id, status);
CREATE INDEX idx_wake_rules_goal ON wake_rules (goal_id);
CREATE INDEX idx_wake_rules_root_rule ON wake_rules (root_rule_id);
CREATE INDEX idx_wake_rules_status_event_kind ON wake_rules (status, event_kind);

