  "id" TEXT NOT NULL,
  "workspace_id" TEXT NOT NULL,
  "user_id" TEXT NOT NULL,
  "repo_id" TEXT NOT NULL REFERENCES repos (id) ON DELETE CASCADE,
  "level" TEXT NOT NULL DEFAULT 'read' CHECK("level" IN ('read', 'review', 'write')),
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)),
  PRIMARY KEY ("id")
);
CREATE INDEX idx_member_repo_grants_repo ON workspace_member_repo_grants (repo_id);
CREATE UNIQUE INDEX uq_member_repo_grants_user_repo ON workspace_member_repo_grants (user_id, repo_id);

CREATE TABLE "workspace_members" (
  "id" TEXT NOT NULL,
  "workspace_id" TEXT NOT NULL,
  "user_id" TEXT NOT NULL,
  "role" TEXT NOT NULL DEFAULT 'member' CHECK("role" IN ('owner', 'admin', 'member', 'viewer', 'guest') OR "role" LIKE 'custom:_%'),
  "invited_by" TEXT NULL,
  "joined_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)),
  "display_name" TEXT NULL,
  "email" TEXT NULL,
  "git_author_name" TEXT NULL,
  "git_author_email" TEXT NULL,
  PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX uq_workspace_members_user ON workspace_members (user_id);

CREATE TABLE "workspace_meta" (
  "id" INTEGER NOT NULL DEFAULT 0,
  "workspace_id" TEXT NOT NULL,
  "install_id" TEXT NOT NULL,
  "created_with_schema_version" INTEGER NOT NULL,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)),
  PRIMARY KEY ("id")
);

CREATE TABLE "workspace_roles" (
  "id" TEXT NOT NULL,
  "workspace_id" TEXT NOT NULL,
  "name" TEXT NOT NULL,
  "base_preset" TEXT NOT NULL CHECK("base_preset" IN ('admin', 'member', 'viewer', 'guest')),
  "denied_permissions" TEXT NOT NULL DEFAULT '[]' CHECK(json_valid("denied_permissions") AND json_type("denied_permissions") = 'array'),
  "created_by" TEXT NULL,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)),
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)),
  PRIMARY KEY ("id"),
  UNIQUE ("name")
);

CREATE TABLE "workspace_settings" (
  "workspace_id" TEXT NOT NULL,
  "key" TEXT NOT NULL,
  "value" TEXT NOT NULL,
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)),
  PRIMARY KEY ("key", "workspace_id")
);

CREATE TABLE "write_ledger" (
  "workspace_id" TEXT NOT NULL,
  "idempotency_key" TEXT NOT NULL,
  "op_name" TEXT NOT NULL,
  "result_json" TEXT NULL CHECK(json_valid("result_json")),
  "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)),
  PRIMARY KEY ("idempotency_key", "workspace_id")
);
CREATE INDEX idx_write_ledger_created ON write_ledger (created_at);
